style.css:
@-moz-document domain("instagram.com") {
/* MAIN BACKGROUND */
body {
    background: #fff5f9 !important;
}

/* LEFT SIDEBAR */
nav {
    background: #fffafb !important;
    border-right: 1px solid #f3d6df !important;
}

/* TOP STORIES AREA */
section {
    background: #ffffff !important;
}

/* POSTS */
article {
    background: #ffffff !important;
    border: 1px solid #f3d6df !important;
    border-radius: 12px !important;
}

/* RIGHT SIDEBAR (suggested users) */
aside {
    background: transparent !important;
}

/* TEXT */
span, div, a {
    color: #5a3b45 !important;
}

/* FOLLOW BUTTON */
button {
    background: #ffc7da !important;
    border: none !important;
    border-radius: 8px !important;
    color: #5a3b45 !important;
}

/* BUTTON HOVER */
button:hover {
    background: #ffb3cc !important;
}

/* INPUTS */
input, textarea {
    background: #ffffff !important;
    border: 1px solid #f3d6df !important;
}

/* STORY RINGS (slight pink tint) */
canvas {
    filter: hue-rotate(310deg) saturate(0.6) !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-track {
    background: #fff5f9;
}

::-webkit-scrollbar-thumb {
    background: #f3d6df;
    border-radius: 10px;
}
}
